70: // ============================================================================
71: // Distributed / Atomic Lock Abstraction (Fail-Fast, Lease + Fencing Token)
72: // ============================================================================
73: 
74: export interface LockLease {
75:   resourceKey: string;
76:   ownerToken: string;
77:   fencingToken: number;
78:   expiresAtMs: number;
79: }
80: 
81: export interface DistributedLockManager {
82:   /**
83:    * Non-blocking atomic lock acquisition (equivalent to Redis `SET key token NX PX ttl`
84:    * or PostgreSQL `pg_try_advisory_xact_lock`). Returns null immediately on contention
85:    * so circular wait / deadlock can never occur.
86:    */
87:   tryAcquire(resourceKey: string, ttlMs: number): LockLease | null;
88: 
89:   /**
90:    * Releases the lock only if the caller still owns the exact ownerToken
91:    * (equivalent to Redis Lua compare-and-delete script).
92:    */
93:   release(lease: LockLease): boolean;
94: }
95: 
96: export class InMemoryAtomicLockManager implements DistributedLockManager {
97:   private readonly locks = new Map<string, LockLease>();
98:   private fencingCounter = 0;
99: 
100:   tryAcquire(resourceKey: string, ttlMs: number): LockLease | null {
101:     const now = Date.now();
102:     const existing = this.locks.get(resourceKey);
103: 
104:     // Purge expired lease to prevent orphaned locks after worker crashes
105:     if (existing && existing.expiresAtMs > now) {
106:       return null;
107:     }
108: 
109:     const lease: LockLease = {
110:       resourceKey,
111:       ownerToken: randomUUID(),
112:       fencingToken: ++this.fencingCounter,
113:       expiresAtMs: now + ttlMs,
114:     };
115: 
116:     this.locks.set(resourceKey, lease);
117:     return lease;
118:   }
119: 
120:   release(lease: LockLease): boolean {
121:     const current = this.locks.get(lease.resourceKey);
122:     if (!current || current.ownerToken !== lease.ownerToken) {
123:       return false;
124:     }
125:     this.locks.delete(lease.resourceKey);
126:     return true;
127:   }
128: 
129:   getActiveLockCount(): number {
130:     const now = Date.now();
131:     let count = 0;
132:     for (const lease of this.locks.values()) {
133:       if (lease.expiresAtMs > now) count++;
134:     }
135:     return count;
136:   }
137: }
