139: // ============================================================================
140: // Strict Idempotency Key Deduplication Store
141: // ============================================================================
142: 
143: export type IdempotencyClaimResult =
144:   | { outcome: "CLAIMED" }
145:   | { outcome: "IN_PROGRESS" }
146:   | { outcome: "PAYLOAD_MISMATCH" }
147:   | { outcome: "COMPLETED"; cachedResponse: CheckoutSuccessBody };
148: 
149: interface IdempotencyRecord {
150:   key: string;
151:   payloadHash: string;
152:   status: "IN_PROGRESS" | "COMPLETED";
153:   cachedResponse?: CheckoutSuccessBody;
154:   expiresAtMs: number;
155: }
156: 
157: export interface IdempotencyStore {
158:   tryClaim(key: string, payloadHash: string, ttlMs: number): IdempotencyClaimResult;
159:   complete(key: string, response: CheckoutSuccessBody, ttlMs: number): void;
160:   release(key: string): void;
161: }
162: 
163: export class InMemoryIdempotencyStore implements IdempotencyStore {
164:   private readonly records = new Map<string, IdempotencyRecord>();
165: 
166:   tryClaim(key: string, payloadHash: string, ttlMs: number): IdempotencyClaimResult {
167:     const now = Date.now();
168:     const existing = this.records.get(key);
169: 
170:     if (existing && existing.expiresAtMs > now) {
171:       if (existing.payloadHash !== payloadHash) {
172:         return { outcome: "PAYLOAD_MISMATCH" };
173:       }
174:       if (existing.status === "IN_PROGRESS") {
175:         return { outcome: "IN_PROGRESS" };
176:       }
177:       if (existing.status === "COMPLETED" && existing.cachedResponse) {
178:         return { outcome: "COMPLETED", cachedResponse: existing.cachedResponse };
179:       }
180:     }
181: 
182:     // Atomic compare-and-set into IN_PROGRESS state
183:     this.records.set(key, {
184:       key,
185:       payloadHash,
186:       status: "IN_PROGRESS",
187:       expiresAtMs: now + ttlMs,
188:     });
189: 
190:     return { outcome: "CLAIMED" };
191:   }
192: 
193:   complete(key: string, response: CheckoutSuccessBody, ttlMs: number): void {
194:     const existing = this.records.get(key);
195:     if (!existing) return;
196: 
197:     this.records.set(key, {
198:       ...existing,
199:       status: "COMPLETED",
200:       cachedResponse: response,
201:       expiresAtMs: Date.now() + ttlMs,
202:     });
203:   }
204: 
205:   release(key: string): void {
206:     const existing = this.records.get(key);
207:     if (existing && existing.status === "IN_PROGRESS") {
208:       this.records.delete(key);
209:     }
210:   }
211: }
