213: // ============================================================================
214: // Vehicle Reservation Repository (Reserve-Before-Capture Storage)
215: // ============================================================================
216: 
217: export class ReservationConflictError extends Error {
218:   constructor(
219:     public readonly code: "VEHICLE_ALREADY_RESERVED" | "BOOKING_ALREADY_CONFIRMED",
220:     message: string
221:   ) {
222:     super(message);
223:     this.name = "ReservationConflictError";
224:   }
225: }
226: 
227: export interface ReservationRepository {
228:   createPendingHold(params: {
229:     bookingId: string;
230:     vehicleId: string;
231:     customerId: string;
232:     fencingToken: number;
233:   }): Promise<VehicleReservation>;
234: 
235:   confirmHold(
236:     reservationId: string,
237:     paymentCaptureId: string,
238:     fencingToken: number
239:   ): Promise<VehicleReservation>;
240: 
241:   releaseHold(reservationId: string): Promise<void>;
242:   getConfirmedReservations(): VehicleReservation[];
243: }
244: 
245: export class InMemoryReservationRepository implements ReservationRepository {
246:   private readonly reservations = new Map<string, VehicleReservation>();
247:   private readonly highestFencingTokenByVehicle = new Map<string, number>();
248: 
249:   constructor(private readonly simulatedDbLatencyMs = 15) {}
250: 
251:   async createPendingHold(params: {
252:     bookingId: string;
253:     vehicleId: string;
254:     customerId: string;
255:     fencingToken: number;
256:   }): Promise<VehicleReservation> {
257:     await delay(this.simulatedDbLatencyMs);
258: 
259:     // Enforce monotonic fencing token to reject stale lock holders
260:     const lastToken = this.highestFencingTokenByVehicle.get(params.vehicleId) ?? 0;
261:     if (params.fencingToken < lastToken) {
262:       throw new ReservationConflictError(
263:         "VEHICLE_ALREADY_RESERVED",
264:         `Stale fencing token for vehicle '${params.vehicleId}'.`
265:       );
266:     }
267: 
268:     for (const existing of this.reservations.values()) {
269:       if (existing.status === "RELEASED") continue;
270: 
271:       if (existing.bookingId === params.bookingId && existing.status === "CONFIRMED") {
272:         throw new ReservationConflictError(
273:           "BOOKING_ALREADY_CONFIRMED",
274:           `Booking '${params.bookingId}' is already confirmed.`
275:         );
276:       }
277: 
278:       if (existing.vehicleId === params.vehicleId) {
279:         throw new ReservationConflictError(
280:           "VEHICLE_ALREADY_RESERVED",
281:           `Vehicle '${params.vehicleId}' already has an active ${existing.status} hold.`
282:         );
283:       }
284:     }
285: 
286:     this.highestFencingTokenByVehicle.set(params.vehicleId, params.fencingToken);
287: 
288:     const nowIso = new Date().toISOString();
289:     const reservation: VehicleReservation = {
290:       reservationId: `res_${randomUUID().slice(0, 8)}`,
291:       bookingId: params.bookingId,
292:       vehicleId: params.vehicleId,
293:       customerId: params.customerId,
294:       status: "PENDING",
295:       fencingToken: params.fencingToken,
296:       createdAt: nowIso,
297:       updatedAt: nowIso,
298:     };
299: 
300:     this.reservations.set(reservation.reservationId, reservation);
301:     return { ...reservation };
302:   }
303: 
304:   async confirmHold(
305:     reservationId: string,
306:     paymentCaptureId: string,
307:     fencingToken: number
308:   ): Promise<VehicleReservation> {
309:     await delay(this.simulatedDbLatencyMs);
310: 
311:     const existing = this.reservations.get(reservationId);
312:     if (!existing) {
313:       throw new Error(`Reservation '${reservationId}' not found during confirmation.`);
314:     }
315:     if (existing.fencingToken !== fencingToken) {
316:       throw new ReservationConflictError(
317:         "VEHICLE_ALREADY_RESERVED",
318:         `Fencing token mismatch confirming reservation '${reservationId}'.`
319:       );
320:     }
321: 
322:     const confirmed: VehicleReservation = {
323:       ...existing,
324:       status: "CONFIRMED",
325:       paymentCaptureId,
326:       updatedAt: new Date().toISOString(),
327:     };
328: 
329:     this.reservations.set(reservationId, confirmed);
330:     return { ...confirmed };
331:   }
332: 
333:   async releaseHold(reservationId: string): Promise<void> {
334:     await delay(Math.min(this.simulatedDbLatencyMs, 5));
335:     const existing = this.reservations.get(reservationId);
336:     if (!existing || existing.status === "CONFIRMED") return;
337: 
338:     this.reservations.set(reservationId, {
339:       ...existing,
340:       status: "RELEASED",
341:       updatedAt: new Date().toISOString(),
342:     });
343:   }
344: 
345:   getConfirmedReservations(): VehicleReservation[] {
346:     return [...this.reservations.values()]
347:       .filter((r) => r.status === "CONFIRMED")
348:       .map((r) => ({ ...r }));
349:   }
350: 
351:   getAllReservations(): VehicleReservation[] {
352:     return [...this.reservations.values()].map((r) => ({ ...r }));
353:   }
354: }
