367: export interface PaymentCaptureResult {
368:   captureId: string;
369:   amountIdr: number;
370:   gatewayIdempotencyKey: string;
371: }
372: 
373: export interface PaymentGateway {
374:   capture(request: PaymentCaptureRequest): Promise<PaymentCaptureResult>;
375: }
376: 
377: export class MockPaymentGateway implements PaymentGateway {
378:   public readonly captureHistory: Array<PaymentCaptureRequest & { captureId: string }> = [];
379:   private readonly capturesByIdempotencyKey = new Map<string, PaymentCaptureResult>();
380: 
381:   constructor(
382:     private readonly simulatedLatencyMs = 50,
383:     private shouldFailNext = false
384:   ) {}
385: 
386:   setFailNext(shouldFail: boolean): void {
387:     this.shouldFailNext = shouldFail;
388:   }
389: 
390:   async capture(request: PaymentCaptureRequest): Promise<PaymentCaptureResult> {
391:     await delay(this.simulatedLatencyMs);
392: 
393:     if (this.shouldFailNext) {
394:       this.shouldFailNext = false;
395:       throw new Error("PSP_CARD_DECLINED_OR_TIMEOUT");
396:     }
397: 
398:     // Defense-in-depth: Gateway-level idempotency deduplication
399:     const existing = this.capturesByIdempotencyKey.get(request.gatewayIdempotencyKey);
400:     if (existing) {
401:       return existing;
402:     }
403: 
404:     const result: PaymentCaptureResult = {
405:       captureId: `cap_${randomUUID().slice(0, 8)}`,
406:       amountIdr: request.amountIdr,
407:       gatewayIdempotencyKey: request.gatewayIdempotencyKey,
408:     };
409: 
410:     this.capturesByIdempotencyKey.set(request.gatewayIdempotencyKey, result);
411:     this.captureHistory.push({ ...request, captureId: result.captureId });
412:     return result;
413:   }
414: }
