416: // ============================================================================
417: // Checkout Handler (Atomic Lock + Strict Idempotency + Graceful 409 Conflict)
418: // ============================================================================
419: 
420: export interface CheckoutHandlerOptions {
421:   lockManager: DistributedLockManager;
422:   idempotencyStore: IdempotencyStore;
423:   reservationRepo: ReservationRepository;
424:   paymentGateway: PaymentGateway;
425:   lockTtlMs?: number;
426:   idempotencyInProgressTtlMs?: number;
427:   idempotencyCompletedTtlMs?: number;
428:   defaultAmountIdr?: number;
429: }
430: 
431: export class CheckoutHandler {
432:   private readonly lockManager: DistributedLockManager;
433:   private readonly idempotencyStore: IdempotencyStore;
434:   private readonly reservationRepo: ReservationRepository;
435:   private readonly paymentGateway: PaymentGateway;
436:   private readonly lockTtlMs: number;
437:   private readonly idempotencyInProgressTtlMs: number;
438:   private readonly idempotencyCompletedTtlMs: number;
439:   private readonly defaultAmountIdr: number;
440: 
441:   constructor(options: CheckoutHandlerOptions) {
442:     this.lockManager = options.lockManager;
443:     this.idempotencyStore = options.idempotencyStore;
444:     this.reservationRepo = options.reservationRepo;
445:     this.paymentGateway = options.paymentGateway;
446:     this.lockTtlMs = options.lockTtlMs ?? 15_000;
447:     this.idempotencyInProgressTtlMs = options.idempotencyInProgressTtlMs ?? 30_000;
448:     this.idempotencyCompletedTtlMs = options.idempotencyCompletedTtlMs ?? 24 * 60 * 60 * 1_000;
449:     this.defaultAmountIdr = options.defaultAmountIdr ?? 450_000;
450:   }
451: 
452:   async handle(request: CheckoutRequest): Promise<CheckoutResponse> {
453:     // 1. Validate Idempotency-Key & Payload
454:     const idempotencyKey = request.idempotencyKey?.trim();
455:     if (!idempotencyKey) {
456:       return errorResponse(400, "MISSING_IDEMPOTENCY_KEY", "Header 'Idempotency-Key' is required.", false);
457:     }
458: 
459:     const { payload } = request;
460:     if (!payload?.booking_id?.trim() || !payload?.vehicle_id?.trim() || !payload?.customer_id?.trim()) {
461:       return errorResponse(
462:         400,
463:         "INVALID_REQUEST",
464:         "Fields 'booking_id', 'vehicle_id', and 'customer_id' are required.",
465:         false
466:       );
467:     }
468: 
469:     const amountIdr = payload.amount_idr ?? this.defaultAmountIdr;
470:     const payloadHash = computePayloadHash({
471:       booking_id: payload.booking_id,
472:       vehicle_id: payload.vehicle_id,
473:       customer_id: payload.customer_id,
474:       amount_idr: amountIdr,
475:     });
476: 
477:     // 2. Strict Idempotency Key Deduplication (Atomic Claim)
478:     const claim = this.idempotencyStore.tryClaim(
479:       idempotencyKey,
480:       payloadHash,
481:       this.idempotencyInProgressTtlMs
482:     );
483: 
484:     if (claim.outcome === "PAYLOAD_MISMATCH") {
485:       return errorResponse(
486:         409,
487:         "IDEMPOTENCY_PAYLOAD_MISMATCH",
488:         `Idempotency-Key '${idempotencyKey}' was already used with a different checkout payload.`,
489:         false,
490:         { idempotency_key: idempotencyKey }
491:       );
492:     }
493: 
494:     if (claim.outcome === "IN_PROGRESS") {
495:       return errorResponse(
496:         409,
497:         "IDEMPOTENCY_IN_PROGRESS",
498:         `A checkout request with Idempotency-Key '${idempotencyKey}' is already being processed.`,
499:         true,
500:         { idempotency_key: idempotencyKey, booking_id: payload.booking_id },
501:         { "Retry-After": "2" }
502:       );
503:     }
504: 
505:     if (claim.outcome === "COMPLETED") {
506:       return {
507:         status: 200,
508:         headers: { "X-Idempotent-Replay": "true" },
509:         body: {
510:           ...claim.cachedResponse,
511:           idempotent_replay: true,
512:         },
513:       };
514:     }
515: 
516:     // 3. Acquire Non-Blocking Atomic Lock on Vehicle Resource (Eliminates Deadlock)
517:     const vehicleLockKey = `lock:vehicle:${payload.vehicle_id}`;
518:     const lease = this.lockManager.tryAcquire(vehicleLockKey, this.lockTtlMs);
519: 
520:     if (!lease) {
521:       // Release THIS request's fresh IN_PROGRESS idempotency claim so the caller can retry cleanly later
522:       this.idempotencyStore.release(idempotencyKey);
523:       return errorResponse(
524:         409,
525:         "VEHICLE_LOCK_CONFLICT",
526:         `Vehicle '${payload.vehicle_id}' is currently locked by another concurrent checkout. Please retry after a short delay.`,
527:         true,
528:         { vehicle_id: payload.vehicle_id, booking_id: payload.booking_id },
529:         { "Retry-After": "2" }
530:       );
531:     }
532: 
533:     let pendingHold: VehicleReservation | null = null;
534: 
535:     try {
536:       // 4. Reserve-Before-Capture: Persist PENDING vehicle hold before touching Payment Gateway
537:       pendingHold = await this.reservationRepo.createPendingHold({
538:         bookingId: payload.booking_id,
539:         vehicleId: payload.vehicle_id,
540:         customerId: payload.customer_id,
541:         fencingToken: lease.fencingToken,
542:       });
543: 
544:       // 5. Execute Idempotent Payment Capture ONLY after vehicle hold is atomically secured
545:       const gatewayIdempotencyKey = `capture:${payload.booking_id}:${idempotencyKey}`;
546:       const captureResult = await this.paymentGateway.capture({
547:         bookingId: payload.booking_id,
548:         customerId: payload.customer_id,
549:         amountIdr,
550:         gatewayIdempotencyKey,
551:       });
552: 
553:       // 6. Confirm Vehicle Hold with Fencing Token verification
554:       const confirmedReservation = await this.reservationRepo.confirmHold(
555:         pendingHold.reservationId,
556:         captureResult.captureId,
557:         lease.fencingToken
558:       );
559: 
560:       const successBody: CheckoutSuccessBody = {
561:         ok: true,
562:         idempotent_replay: false,
563:         reservation: confirmedReservation,
564:         payment: {
565:           capture_id: captureResult.captureId,
566:           amount_idr: captureResult.amountIdr,
567:           gateway_idempotency_key: captureResult.gatewayIdempotencyKey,
568:         },
569:       };
570: 
571:       // 7. Persist Completed Idempotency Record
572:       this.idempotencyStore.complete(idempotencyKey, successBody, this.idempotencyCompletedTtlMs);
573: 
574:       return {
575:         status: 201,
576:         headers: { "X-Idempotent-Replay": "false" },
577:         body: successBody,
578:       };
579:     } catch (err) {
580:       // Compensating action: release pending hold if payment or confirmation failed
581:       if (pendingHold) {
582:         await this.reservationRepo.releaseHold(pendingHold.reservationId);
583:       }
584: 
585:       // Release IN_PROGRESS idempotency claim on failure/conflict
586:       this.idempotencyStore.release(idempotencyKey);
587: 
588:       if (err instanceof ReservationConflictError) {
589:         return errorResponse(409, err.code, err.message, false, {
590:           vehicle_id: payload.vehicle_id,
591:           booking_id: payload.booking_id,
592:         });
593:       }
594: 
595:       const reason = err instanceof Error ? err.message : "Unknown payment gateway error";
596:       return errorResponse(
597:         502,
598:         "PAYMENT_CAPTURE_FAILED",
599:         `Payment capture failed and pending vehicle hold was safely released: ${reason}`,
600:         true,
601:         { booking_id: payload.booking_id, vehicle_id: payload.vehicle_id }
602:       );
603:     } finally {
604:       // Always release atomic distributed lock using owner-verified compare-and-delete
605:       this.lockManager.release(lease);
606:     }
607:   }
608: }
