610: // ============================================================================
611: // Helpers
612: // ============================================================================
613: 
614: function computePayloadHash(payload: Required<CheckoutPayload>): string {
615:   const canonical = JSON.stringify({
616:     amount_idr: payload.amount_idr,
617:     booking_id: payload.booking_id,
618:     customer_id: payload.customer_id,
619:     vehicle_id: payload.vehicle_id,
620:   });
621:   return createHash("sha256").update(canonical).digest("hex");
622: }
623: 
624: function errorResponse(
625:   status: 400 | 409 | 502,
626:   code: CheckoutErrorCode,
627:   message: string,
628:   retryable: boolean,
629:   details?: Record<string, unknown>,
630:   extraHeaders: Record<string, string> = {}
631: ): CheckoutResponse {
632:   return {
633:     status,
634:     headers: { ...extraHeaders },
635:     body: {
636:       ok: false,
637:       error: {
638:         code,
639:         message,
640:         retryable,
641:         ...(details ? { details } : {}),
642:       },
643:     },
644:   };
645: }
646: 
647: function delay(ms: number): Promise<void> {
648:   return new Promise((resolve) => setTimeout(resolve, ms));
649: }

