    ok: true,
    idempotent_replay: false,
    reservation: confirmedReservation,
    payment: {
      capture_id: captureResult.captureId,
      amount_idr: captureResult.amountIdr,
      gateway_idempotency_key: captureResult.gatewayIdempotencyKey,
    },
  };

